pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: depositor pays amount, attacker contract address is constructed by deploying helper
    function testFuzz_property(address depositor, uint256 depositAmount) public {
        // keep domain sensible but wide
        vm.assume(depositor != address(0));
        depositAmount = bound(depositAmount, 1, 1 ether);

        // Deploy a helper that will revert on receive to act as adversarial callee
        Reverter rev = new Reverter();

        // Fund depositor so they can send ether to c via fallback
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        // deposit into c by triggering fallback
        (bool okDeposit, ) = address(c).call{value: depositAmount}("");
        require(okDeposit);

        // Record balances mapping for the reverter address before withdraw
        uint256 before = c.balances(address(rev));

        // Now prank depositor to call withdraw which will attempt to send funds to msg.sender (depositor)
        // But we want to exercise the adversarial external behaviour: the mutant ignores call result when sending to msg.sender
        // To make the failing send observable on some key k != msg.sender, we simulate by having the reverter also have a balance
        // so that the general property is: withdraw should not clear balances[k] for other addresses. Ensure rev has non-zero balance mapping.
        // Fund and deposit from rev via self-destruct pattern: have an external account call fallback on c as if from rev

        // To give rev a positive recorded balance in c, have an EOA send to c but set msg.sender to rev by using vm.prank
        vm.deal(address(this), 0.1 ether);
        // impersonate rev to deposit into c
        vm.prank(address(rev));
        (bool okDepositRev, ) = address(c).call{value: 0.1 ether}("");
        require(okDepositRev);

        // Confirm rev's recorded balance is positive
        uint256 revBalanceBefore = c.balances(address(rev));
        require(revBalanceBefore > 0);

        // Now have depositor call withdraw. Use vm.prank to set msg.sender = depositor
        vm.prank(depositor);
        // Call withdraw. The reference will attempt to send depositor their balance and revert if send fails.
        // Our Reverter does not participate in this call, but the property we assert is that balances[address(rev)] remains unchanged after withdraw.
        // This distinguishes reference (which maintains other addresses' balances) from mutant that can zero balances incorrectly when send result is ignored.
        try c.withdraw() {
            // ok
        } catch {
            // If reference reverts because send failed to depositor, that's still fine; property about rev's balance must hold in reference always
        }

        uint256 revBalanceAfter = c.balances(address(rev));

        // General property: withdraw does not modify balances[k] for other addresses k (here k = address(rev)).
        // The reference satisfies this for all inputs; the mutant that clears balances regardless of send result can make revBalanceAfter == 0 for some inputs.
        assertTrue(revBalanceAfter == revBalanceBefore);
    }
}

// Adversarial helper that reverts on any receive/call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: depositor (the account whose balance will be nonzero and then call withdraw),
    // other (another account whose balance should remain unchanged), and amount to deposit.
    function testFuzz_property(address depositor, address other, uint256 amount) public {
        // Keep addresses non-zero and distinct to avoid degenerate cases
        vm.assume(depositor != address(0));
        vm.assume(other != address(0));
        // allow other to possibly equal depositor? The property is about k != caller, so require distinct
        vm.assume(depositor != other);
        // bound amount to a reasonable range so vm.deal works and to avoid overflow in tests
        amount = bound(amount, 1, 1 ether);

        // Fund both accounts so they can deposit
        vm.deal(depositor, amount);
        vm.deal(other, amount);

        // Have both deposit by sending to fallback
        vm.prank(depositor);
        (bool s1, ) = address(c).call{value: amount}("0x6c17468c"); // call fallback via arbitrary calldata
        // fallback is payable and will accept plain value; ignore s1 because deposit should succeed

        vm.prank(other);
        (bool s2, ) = address(c).call{value: amount}("");
        // check deposits succeeded at least in test environment
        vm.assume(s1 && s2);

        // Record other's balance before withdraw
        uint256 beforeOther = c.balances(other);

        // Now arrange that depositor is a contract that will make the low-level call fail when receiving funds.
        // We need to deploy a Reverter contract and have c.send to depositor fail. However, c calls msg.sender.call,
        // so we must perform withdraw while msg.sender is the reverter contract address. To do that, we deploy
        // a wrapper contract that holds the depositor role and forwards deposits to c, but on withdraw the low-level
        // call from c will target that wrapper which will revert on receive.

        // Deploy adversarial wrapper with depositor identity; fund it so it can have balance when calling fallback
        RevertingReceiver adv = new RevertingReceiver(address(c));

        // Fund the adversarial wrapper and deposit into c on its behalf by calling fallback
        vm.deal(address(adv), amount);
        // adv will forward plain value to c.fallback by calling c with value
        adv.deposit{value: amount}();

        // Ensure adv is the caller for withdraw: call withdraw from adv
        // adv will call c.withdraw() in a context where msg.sender == adv
        // No need to vm.prank since adv initiates the call itself

        // Execute withdraw from adv; capture success via try/catch pattern
        bool ok;
        try adv.callWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // After withdraw completes (regardless of revert), the reference guarantees that other's balance is unchanged
        // We assert that c.balances(other) == beforeOther. This holds for the reference for all admissible inputs;
        // the mutant that ignores the send result and still clears balances[msg.sender] can cause balances[other]
        // to become different for some inputs (e.g., if adv triggers different msg.sender semantics), and the fuzzer
        // will find such an input.
        assertTrue(c.balances(other) == beforeOther);
    }
}

// Adversarial helper: a contract that forwards deposits to C but reverts on receiving Ether from C (so low-level call fails)
contract RevertingReceiver {
    address immutable target;
    constructor(address _target) { target = _target; }
    // deposit into target by sending value to its fallback
    function deposit() external payable {
        (bool s, ) = target.call{value: msg.value}("");
        require(s, "deposit failed");
    }
    // called to invoke withdraw on target
    function callWithdraw() external {
        C(target).withdraw();
    }
    // revert on receive to simulate a failing low-level call from target
    receive() external payable {
        revert("can't accept");
    }
}

