import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor (who funds the contract via fallback) and attacker address k whose balance we observe
    function testFuzz_property(address depositor, address k, uint256 deposit) public {
        // keep deposit within reasonable bounds and nonzero
        deposit = bound(deposit, 1, 1 ether);
        // avoid zero addresses for actors
        vm.assume(depositor != address(0));
        vm.assume(k != address(0));

        // Deploy a helper that will REVERT on receiving funds to simulate a failing external call target
        Reverter rev = new Reverter();

        // Fund depositor so they can send ether
        vm.deal(depositor, deposit);

        // depositor sends deposit to contract c via fallback, increasing balances[depositor]
        vm.prank(depositor);
        (bool sent,) = address(c).call{value: deposit}("");
        require(sent);

        // Also set balances[k] to a nonzero value by having k deposit some Ether (if k==depositor this just increases their balance)
        vm.deal(k, deposit);
        vm.prank(k);
        (bool sent2,) = address(c).call{value: deposit}("");
        require(sent2);

        // Observe balances[k] before withdraw
        uint256 before = c.balances(k);

        // Now invoke withdraw as depositor but make msg.sender be the Reverter contract to simulate a failing external call target
        // The contract's withdraw will attempt to call msg.sender (the depositor in normal runs). To cause the low-level call from C to fail,
        // we need msg.sender of that low-level call to be a contract that will revert when receiving Ether. That requires that C's low-level call targets msg.sender,
        // so we instead make the depositor be the Reverter contract. To do this, deploy a forwarding contract that will act as depositor and then call C's fallback,
        // but for the withdraw call we want msg.sender to be the Reverter. Simpler: use vm.prank to make the call originate from the Reverter address by making a contract at that address.

        // We cannot change the address of an existing deployed contract, so instead perform withdraw while the depositor is an EOA but have the withdraw's low-level call target be the Reverter by making the contract's msg.sender equal to the Reverter when it receives the low-level call. That happens because C does: msg.sender.call{value: ...}(""); which targets msg.sender — the withdraw caller. So to make the low-level call target revert, we must call withdraw from the Reverter contract.
        // Thus we need the Reverter contract to hold the balance in c. To achieve that, have the Reverter deposit deposit into c (so balances[reverter]==deposit), then call withdraw from the Reverter.

        // Deploy helper Attacker that can deposit then call withdraw; but Attacker will have Reverter's failing receive to cause the low-level call to revert.
        Attacker attacker = new Attacker(c);
        // fund attacker then have it deposit into c
        vm.deal(address(attacker), deposit);
        attacker.deposit{value: deposit}();

        // also ensure k's balance snapshot includes possible overlap with attacker; observe balances[k] again if k==address(attacker)
        uint256 before2 = c.balances(k);

        // Now call withdraw from attacker: the low-level call to msg.sender (attacker) will revert because Attacker's fallback reverts via Reverter pattern
        attacker.callWithdraw();

        // Observe balances[k] after withdraw
        uint256 after = c.balances(k);

        // General rule (single assertion): on the correct contract, balances[k] is unchanged by withdraw performed by another account whose external receive reverts (the contract reverts on failed send so balances remain unchanged);
        // thus balances[k] == before for all inputs. The mutant that ignores the send result will clear balances[msg.sender] despite the failed send, causing some k to differ.
        assertTrue(after == before);
    }
}

// Helper that reverts on receive to simulate failing low-level call target
contract Reverter {
    fallback() external payable {
        revert("fail");
    }
}

// Attacker deposits then calls withdraw; its fallback delegates to Reverter to revert on receiving funds
contract Attacker {
    C c;
    Reverter r = new Reverter();
    constructor(C _c) { c = _c; }
    function deposit() external payable {
        // deposit into c so c.balances(address(this)) increases
        (bool ok,) = address(c).call{value: msg.value}("");
        require(ok);
    }
    function callWithdraw() external {
        // call withdraw; when c attempts msg.sender.call{{value:...}}(""), it will target this contract and its fallback will revert
        c.withdraw();
    }
    fallback() external payable {
        // delegate to reverter by calling its fallback, which will revert
        (bool ok,) = address(r).call{value: msg.value}("");
        require(ok);
    }
}

