contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 deposit, uint128 extra) public {
        // keep amounts reasonable but wide
        uint256 dep = uint256(bound(deposit, 1, type(uint128).max));
        uint256 ext = uint256(bound(extra, 0, 1)); // extra decides whether attacker reenters (0 or 1)

        // Deploy attacker that will try to reenter during withdraw when ext == 1
        Attacker attacker = new Attacker(c);

        // Fund attacker and contract
        vm.deal(address(attacker), dep + 1 ether);
        vm.deal(address(this), 1 ether);

        // Attacker deposits dep into c by calling fallback (send ether)
        vm.prank(address(attacker));
        (bool ok,) = address(c).call{value: dep}((""));
        require(ok);

        // Also give contract some extra funds donated by this test to make draining meaningful
        vm.prank(address(this));
        (bool ok2,) = address(c).call{value: 1 ether}((""));
        require(ok2);

        // Record contract balance before withdraw
        uint256 before = address(c).balance;

        // If ext==1, make attacker reentrant; attacker will reenter once during withdraw
        attacker.setReenter(ext == 1);

        // Trigger withdraw from attacker
        vm.prank(address(attacker));
        attacker.doWithdraw();

        // After withdraw completes, the correct contract with the lock guarantee ensures
        // that the contract's balance equals before - withdrawnAmount (i.e., it decreased exactly by deposit)
        // We observe this via: address(c).balance + c.balances(attacker) == before
        // This must hold for all inputs on the reference; removing the lock allows reentrancy so it can fail for some inputs.
        assertTrue(address(c).balance + c.balances(address(attacker)) == before);
    }
}

// Minimal re-entrant attacker that on receiving ether will call withdraw again if allowed
contract Attacker {
    C public target;
    bool public reenter;
    constructor(C _t) { target = _t; }
    function setReenter(bool r) external { reenter = r; }
    // deposit is done by sending ether to target (fallback in target)
    function doWithdraw() external {
        target.withdraw();
    }
    receive() external payable {
        if (reenter) {
            reenter = false; // one reentry
            // reenter withdraw
            target.withdraw();
        }
    }
}

