// Minimal adversarial helper that will attempt reentrancy during its receive() when withdraw triggers an external call.
contract Attacker {
    C immutable target;
    uint256 public reentryNonce;
    uint256 internal entered;

    constructor(address _target) {
        target = C(_target);
    }

    // allow test to set a nonce to vary behavior (fuzzed indirectly)
    function setReentryNonce(uint256 n) external { reentryNonce = n; }

    // deposit into target by sending ETH to fallback
    function deposit() external payable {
        // nothing else; target's fallback will credit balances[msg.sender]
    }

    // trigger withdraw from this contract
    function triggerWithdraw() external {
        // call withdraw as this contract
        target.withdraw();
    }

    // receive will be invoked when target.call sends ETH to this attacker during withdraw.
    // It will attempt reentrant withdraw calls up to a small bounded number derived from reentryNonce
    receive() external payable {
        // use reentryNonce to decide how many times to attempt reentrancy, but cap it small to avoid gas exhaustion
        uint256 attempts = (reentryNonce % 3);
        if (entered < attempts) {
            entered += 1;
            // try to reenter
            // we don't catch revert here; if reentry fails the call reverts only this receive and withdraw will revert
            // but in the mutant (no lock) the reentry may succeed and drain more funds
            target.withdraw();
        }
    }
}

